    const timestampMatch = keys.find(k => k.includes('1780345494958'));
    if (timestampMatch) return timestampMatch;
    const stringMatch = keys.find(k => k.toLowerCase().replace(/_/g, ' ').includes('mandataire 1780345494958'));
